{
  "version": 0,
  "description": "MyApp: a web API on one cloud",
  "environments": [
    {"id": "prod", "label": "Production", "kind": "production"}
  ],
  "groups": [
    {"id": "myapp-aws", "kind": "account", "provider": "aws", "label": "MyApp account"},
    {"id": "tokyo", "kind": "region", "region": "ap-northeast-1", "parent": "myapp-aws"},
    {"id": "app-net", "kind": "subnet", "parent": "tokyo", "visibility": "private"}
  ],
  "nodes": [
    {"id": "web", "category": "client", "label": "Browser"},
    {"id": "lb", "category": "load_balancer", "service": "elb.alb", "group": "tokyo"},
    {"id": "shop-api", "category": "compute.container", "service": "ecs.fargate", "group": "app-net", "count": 2,
     "spec": [{"key": "cpu", "value": "512"}, {"key": "memory_mb", "value": "1024"}]},
    {"id": "items-db", "category": "database.relational", "service": "rds.postgres", "group": "app-net",
     "engine": "postgres 16",
     "spec": [{"key": "instance_class", "value": "db.t3.medium"}, {"key": "storage_gb", "value": "50"}]}
  ],
  "edges": [
    {"from": "web", "to": "lb", "protocol": "https"},
    {"from": "lb", "to": "shop-api", "protocol": "http"},
    {"from": "shop-api", "to": "items-db", "protocol": "postgres"}
  ],
  "flows": [
    {"id": "list-items", "label": "Open the item list", "start": "web", "trigger": "user", "steps": [
      {"from": "web", "to": "lb", "action": "request", "label": "GET /api/items"},
      {"from": "lb", "to": "shop-api", "action": "request"},
      {"from": "shop-api", "to": "items-db", "action": "read"},
      {"from": "items-db", "to": "shop-api", "action": "response"},
      {"from": "shop-api", "to": "lb", "action": "response"},
      {"from": "lb", "to": "web", "action": "response"}
    ]}
  ]
}
